import { bindTopologyNodeSelected, dispatchTopologyNavigate, type TopologyNavigateDetail, type TopologyNodeSelectedDetail } from "./selectionContract.ts";

export interface TopologyPageControllerOptions {
  scene: EventTarget | null;
  onNodeSelected: (detail: TopologyNodeSelectedDetail) => void;
  onNavigate?: (detail: TopologyNavigateDetail) => void;
  onNavigationStateChange?: (active: boolean) => void;
  onNavigationComplete?: () => void;
  onNavigationCancel?: () => void;
}

export interface TopologyPageController {
  navigate(detail: TopologyNavigateDetail): void;
  destroy(): void;
}

export function createTopologyPageController({ scene, onNodeSelected, onNavigate, onNavigationStateChange, onNavigationComplete, onNavigationCancel }: TopologyPageControllerOptions): TopologyPageController {
  const destroyNodeSelected = bindTopologyNodeSelected(scene, onNodeSelected);

  const navigationListener = (event: Event) => {
    const customEvent = event as CustomEvent<TopologyNavigateDetail>;
    const detail = customEvent.detail;
    if (!detail?.toId) return;
    onNavigate?.(detail);
  };

  const navigationStateListener = () => {
    onNavigationStateChange?.(true);
  };

  const navigationCompleteListener = () => {
    onNavigationStateChange?.(false);
    onNavigationComplete?.();
  };

  const navigationCancelListener = () => {
    onNavigationStateChange?.(false);
    onNavigationCancel?.();
  };

  scene?.addEventListener("topology-navigate", navigationListener);
  scene?.addEventListener("topology-navigation-state", navigationStateListener);
  scene?.addEventListener("topology-navigation-complete", navigationCompleteListener);
  scene?.addEventListener("topology-navigation-cancel", navigationCancelListener);

  return {
    navigate(detail) {
      dispatchTopologyNavigate(scene, detail);
    },
    destroy() {
      destroyNodeSelected();
      scene?.removeEventListener("topology-navigate", navigationListener);
      scene?.removeEventListener("topology-navigation-state", navigationStateListener);
      scene?.removeEventListener("topology-navigation-complete", navigationCompleteListener);
      scene?.removeEventListener("topology-navigation-cancel", navigationCancelListener);
    },
  };
}
